private fun java.io.InputStream.readNBytesCompat(max:Int):ByteArray{val out=java.io.ByteArrayOutputStream();val b=ByteArray(8192);while(true){val n=read(b);if(n<0)break;require(out.size()+n<=max);out.write(b,0,n)};return out.toByteArray()}
private fun Color.toArgbCompat()=android.graphics.Color.argb((alpha*255).toInt(),(red*255).toInt(),(green*255).toInt(),(blue*255).toInt())
@Composable internal fun Heading(t:String){Text(t,style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)}
@Composable internal fun Panel(modifier:Modifier=Modifier,content:@Composable ColumnScope.()->Unit){Card(modifier.fillMaxWidth(),shape=RoundedCornerShape(22.dp),colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.surface)){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(6.dp),content=content)}}
@Composable internal fun Choice(label:String,value:String,options:List<String>,select:(String)->Unit){var expanded by remember{mutableStateOf(false)};Box{OutlinedButton(onClick={expanded=true},modifier=Modifier.fillMaxWidth()){Text("$label : $value")};DropdownMenu(expanded,{expanded=false}){options.forEach{v->DropdownMenuItem(text={Text(v)},onClick={select(v);expanded=false})}}}}
@Composable private fun Robot(p:Palette,modifier:Modifier){Canvas(modifier){val s=size.minDimension;val x=(size.width-s)/2;val y=(size.height-s)/2;fun pt(a:Float,b:Float):Offset { return Offset(x+a*s,y+b*s) };drawRoundRect(p.main,pt(.12f,.04f),Size(.76f*s,.48f*s),CornerRadius(.15f*s));drawRoundRect(p.bg,pt(.21f,.12f),Size(.58f*s,.30f*s),CornerRadius(.10f*s));drawCircle(p.second,.047f*s,pt(.37f,.27f));drawCircle(p.second,.047f*s,pt(.63f,.27f));drawRoundRect(p.second,pt(.13f,.52f),Size(.74f*s,.43f*s),CornerRadius(.09f*s));val shirt=Path().apply{moveTo(x+.34f*s,y+.53f*s);lineTo(x+.66f*s,y+.53f*s);lineTo(x+.50f*s,y+.90f*s);close()};drawPath(shirt,Color.White);drawRoundRect(p.main,pt(.47f,.55f),Size(.06f*s,.28f*s),CornerRadius(.02f*s))}}
@Composable private fun EntryRow(e:Entry,ac:List<Account>,cats:List<Category>,value:String,p:Palette,edit:()->Unit){Panel{Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(cats.find{it.id==e.category}?.name?:e.kind,fontWeight=FontWeight.Bold);Text(e.date+" · "+e.time.ifBlank{"Heure non renseignée"}+" · "+(ac.find{it.id==e.account}?.name?:"Compte"),fontSize=12.sp);if(e.note.isNotBlank())Text(e.note,fontSize=12.sp)};Text((if(e.kind=="Entrée")"+" else if(e.kind=="Dépense")"−" else "↔ ")+value,color=if(e.kind=="Entrée")p.positive else if(e.kind=="Dépense")p.negative else p.main,fontWeight=FontWeight.Bold)};TextButton(onClick=edit){Text("Détails / modifier")}}}
