@Composable private fun EntryForm(old:Entry?,start:String,ac:List<Account>,cats:List<Category>,balances:Map<String,Long>,policy:String,p:Palette,onCategory:(String,String)->String,onSave:(Entry)->Unit,onDelete:(String)->Unit){
